namespace Calculator;

public static class MathOps
{
    public static int Add(int a, int b) => a + b;

    public static bool IsEven(int n) => n % 2 == 0;

    public static double Divide(double a, double b)
    {
        if (b == 0)
        {
            throw new DivideByZeroException("Divisor must not be zero.");
        }
        return a / b;
    }
}

namespace Calculator.Tests;

public class MathOpsTests
{
    [Fact]
    public void Add_ReturnsSum()
    {
        // Arrange
        int a = 2, b = 3;

        // Act
        int result = MathOps.Add(a, b);

        // Assert
        Assert.Equal(5, result);
    }

    [Theory]
    [InlineData(2, true)]
    [InlineData(7, false)]
    [InlineData(0, true)]
    public void IsEven_DetectsEvenNumbers(int input, bool expected)
    {
        Assert.Equal(expected, MathOps.IsEven(input));
    }

    [Fact]
    public void Divide_ByZero_Throws()
    {
        var ex = Assert.Throws<DivideByZeroException>(() => MathOps.Divide(1, 0));
        Assert.Equal("Divisor must not be zero.", ex.Message);
    }
}

[Fact]
public async Task DelayedValue_IsReturned()
{
    Task<int> work = Task.Run(async () =>
    {
        await Task.Delay(50);
        return 42;
    });

    int value = await work;

    Assert.Equal(42, value);
}
